local VineyardPlanter = {}
local PRODUCTS = {
    table_grape_crop = { name = "Namizno grozdje", grapeVineCost = 1, waterCost = 1, time = 4, cost = 20, yield = 30, description = "Namizno grozdje za prehrano." },
    red_wine_grape = { name = "Rdeče vino grozdje", redVineCost = 1, waterCost = 1, time = 5, cost = 35, yield = 40, prestige = 2, description = "Rdeče vino grozdje za rdeče vino." },
    white_wine_grape = { name = "Belo vino grozdje", whiteVineCost = 1, waterCost = 1, time = 5, cost = 35, yield = 40, prestige = 2, description = "Belo vino grozdje za belo vino." },
    raisin_grape = { name = "Rozinasto grozdje", redVineCost = 1, waterCost = 1, time = 6, cost = 50, yield = 45, prestige = 3, happiness = 1, description = "Rozinasto grozdje za sušenje rozin." },
    silver_cluster_grape = { name = "Srebrno grozd grozdje", redVineCost = 1, silverCost = 1, waterCost = 1, time = 9, cost = 130, yield = 65, prestige = 8, happiness = 2, description = "Grozdje iz srebrnih trt za plemiče." },
    royal_grand_vineyard = { name = "Kraljevski veliki vinograd", redVineCost = 2, whiteVineCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, waterCost = 2, time = 15, cost = 1000, yield = 100, prestige = 35, happiness = 9, description = "Veliki kraljevski vinograd z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Vinogradniška postaja", cost = { gold = 240, wood = 130, stone = 100 }, upkeep = 6, qualityBonus = 5 },
    vineyard = { name = "Vinograd", cost = { gold = 850, wood = 220, stone = 300, water = 10 }, upkeep = 21, qualityBonus = 18 },
    trellis_house = { name = "Rešetka hiša", cost = { gold = 2100, wood = 350, stone = 600, silver = 25, wood2 = 8 }, upkeep = 53, qualityBonus = 30 },
    royal_vineyard_atelier = { name = "Kraljevski atelje vinograda", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
VineyardPlanter.grapeVineStock = 22; VineyardPlanter.redVineStock = 18; VineyardPlanter.whiteVineStock = 18; VineyardPlanter.waterStock = 18; VineyardPlanter.silverStock = 8; VineyardPlanter.goldStock = 6; VineyardPlanter.jewelStock = 6
VineyardPlanter.productStock = {}; VineyardPlanter.buildings = {}; VineyardPlanter.maker = nil; VineyardPlanter.activeMaking = {}; VineyardPlanter.totalProducts = 0; VineyardPlanter.dayTimer = 0
function VineyardPlanter.init() VineyardPlanter.grapeVineStock=22; VineyardPlanter.redVineStock=18; VineyardPlanter.whiteVineStock=18; VineyardPlanter.waterStock=18; VineyardPlanter.silverStock=8; VineyardPlanter.goldStock=6; VineyardPlanter.jewelStock=6; VineyardPlanter.productStock={}; VineyardPlanter.buildings={}; VineyardPlanter.maker=nil; VineyardPlanter.activeMaking={}; VineyardPlanter.totalProducts=0; VineyardPlanter.dayTimer=0; print("[VineyardPlanter] Royal Vineyard Planter System initialized (6 products, 4 buildings)") end
function VineyardPlanter.hireMaker(n,s) s=s or math.random(45,85); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; VineyardPlanter.maker={name=n or ("Vinogradnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vinogradnik najet: %s (spretnost: %d)",VineyardPlanter.maker.name,s),"success") end; return true end
function VineyardPlanter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function VineyardPlanter.build(id) local ok,e=VineyardPlanter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(VineyardPlanter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function VineyardPlanter.getQualityBonus() local b=0; for _,bd in ipairs(VineyardPlanter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function VineyardPlanter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.grapeVineCost and VineyardPlanter.grapeVineStock<(d.grapeVineCost or 0) then return false,"Premalo namiznih trt" end; if d.redVineCost and VineyardPlanter.redVineStock<(d.redVineCost or 0) then return false,"Premalo rdečih trt" end; if d.whiteVineCost and VineyardPlanter.whiteVineStock<(d.whiteVineCost or 0) then return false,"Premalo belih trt" end; if d.waterCost and VineyardPlanter.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and VineyardPlanter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and VineyardPlanter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and VineyardPlanter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #VineyardPlanter.buildings==0 then return false,"Potrebna delavnica" end; if not VineyardPlanter.maker then return false,"Potreben vinogradnik" end; return true end
function VineyardPlanter.make(pt,qty) qty=qty or 10; local ok,e=VineyardPlanter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.grapeVineCost then VineyardPlanter.grapeVineStock=VineyardPlanter.grapeVineStock-d.grapeVineCost*qty end; if d.redVineCost then VineyardPlanter.redVineStock=VineyardPlanter.redVineStock-d.redVineCost*qty end; if d.whiteVineCost then VineyardPlanter.whiteVineStock=VineyardPlanter.whiteVineStock-d.whiteVineCost*qty end; if d.waterCost then VineyardPlanter.waterStock=VineyardPlanter.waterStock-d.waterCost*qty end; if d.silverCost then VineyardPlanter.silverStock=VineyardPlanter.silverStock-d.silverCost*qty end; if d.goldCost then VineyardPlanter.goldStock=VineyardPlanter.goldStock-d.goldCost*qty end; if d.jewelCost then VineyardPlanter.jewelStock=VineyardPlanter.jewelStock-d.jewelCost*qty end; local t=d.time; if VineyardPlanter.maker then t=math.max(1,t-math.floor(VineyardPlanter.maker.skill/12)) end; table.insert(VineyardPlanter.activeMaking,{id="vineyard_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function VineyardPlanter.completeMaking(m) local q=1.0+(VineyardPlanter.getQualityBonus()/100); if VineyardPlanter.maker then q=q+(VineyardPlanter.maker.skill/180) end; q=math.min(2.0,q); VineyardPlanter.productStock[m.productType]=(VineyardPlanter.productStock[m.productType] or 0)+m.quantity; VineyardPlanter.totalProducts=VineyardPlanter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if VineyardPlanter.maker then VineyardPlanter.maker.itemsMade=VineyardPlanter.maker.itemsMade+m.quantity; if math.random()<0.20 then VineyardPlanter.maker.skill=math.min(100,VineyardPlanter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grozdje pridelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"vineyard.completed",{productName=m.productName,yield=m.yield}) end end
function VineyardPlanter.update(dt) if not _G.state then return end; VineyardPlanter.dayTimer=VineyardPlanter.dayTimer+dt; if VineyardPlanter.dayTimer>=30 then VineyardPlanter.dayTimer=0; for i=#VineyardPlanter.activeMaking,1,-1 do local m=VineyardPlanter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then VineyardPlanter.completeMaking(m); table.remove(VineyardPlanter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(VineyardPlanter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if VineyardPlanter.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function VineyardPlanter.getStats() return {grapeVineStock=VineyardPlanter.grapeVineStock,redVineStock=VineyardPlanter.redVineStock,whiteVineStock=VineyardPlanter.whiteVineStock,waterStock=VineyardPlanter.waterStock,silverStock=VineyardPlanter.silverStock,goldStock=VineyardPlanter.goldStock,jewelStock=VineyardPlanter.jewelStock,productStock=VineyardPlanter.productStock,numBuildings=#VineyardPlanter.buildings,hasMaker=VineyardPlanter.maker~=nil,makerName=VineyardPlanter.maker and VineyardPlanter.maker.name or "—",makerSkill=VineyardPlanter.maker and VineyardPlanter.maker.skill or 0,activeMaking=#VineyardPlanter.activeMaking,totalProducts=VineyardPlanter.totalProducts} end
return VineyardPlanter
